insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('7c2795e6-c507-4ed8-82cd-e26bb67ed4a2', 'N4', '人に何かをあげます／さしあげます／やります', 'Cho (biếu, tặng) ai đó cái gì', 'さしあげます (khiêm nhường, cho người trên) / あげます (trung tính, ngang hàng) / やります (cho người dưới, động vật, thực vật)', 'N1は N2に N3を あげます／さしあげます／やります', 'Diễn tả hành động cho/tặng/biếu ai đó một thứ gì, chọn động từ theo quan hệ trên dưới', 'さしあげます: khiêm nhường (cho người trên); あげます: trung tính; やります: cho người dưới/động vật/thực vật', NULL, NULL, '{}', NULL, 43, '人に何かをあげます／さしあげます／やります', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('1c5bbbe5-f37d-4dd4-a9e9-c280135b5aa8', 'N4', '人から／に何かをいただきます／もらいます', 'Nhận từ ai đó cái gì', 'いただきます là khiêm nhường ngữ của もらいます, dùng khi nhận từ người trên', 'N1は N2から／に N3を いただきます／もらいます', 'Diễn tả hành động nhận một thứ gì từ ai đó, hoặc xin ai đó cái gì', 'いただきます: khiêm nhường (nhận từ người trên); もらいます: trung tính', NULL, NULL, '{}', NULL, 43, '人から／に何かをいただきます／もらいます', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('c0fbcf4f-cd0b-4760-a8c0-0dd394bb1978', 'N4', '人が何かをくださいます／くれます', 'Ai đó cho mình cái gì', 'くださいます là kính ngữ của くれます, chủ ngữ là người cho (đối lập với もらう chủ ngữ là người nhận)', 'N1が（は） N2に N3を くださいます／くれます', 'Diễn tả hành động ai đó cho/tặng mình (hoặc người trong nhóm mình) một thứ gì', 'くださいます: kính ngữ (người trên cho mình); くれます: trung tính', NULL, NULL, '{}', NULL, 43, '人が何かをくださいます／くれます', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('02004a84-aee7-41ab-8666-63043678f338', 'N4', '人に何かをVて＋さしあげます／あげます／やります', 'N1 làm V cho N2 (ban ơn, giúp đỡ)', 'Thêm て-form trước あげる/さしあげる/やる để diễn tả làm hành động đó vì lợi ích người khác', 'N1は N2に N3をV(て形) さしあげます／あげます／やります', 'Diễn tả hành động làm gì đó cho ai đó (có sắc thái ban ơn nếu dùng với người trên)', 'さしあげます: khiêm nhường (làm cho người trên); あげます: trung tính; やります: cho người dưới/động vật/thực vật', NULL, NULL, '{}', NULL, 43, '人に何かをVて＋さしあげます／あげます／やります', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('252e27db-87a4-48a2-b960-0366589b2dc2', 'N4', '人に何かをVていただきます／Vてもらいます', 'Nhờ/để ai đó làm gì cho mình', 'Chủ ngữ là người nhận lợi ích (mình), いただきます là khiêm nhường ngữ', 'N1は N2に N3をV(て形) いただきます／もらいます', 'Diễn tả việc mình nhờ/được ai đó làm gì đó cho mình', 'いただきます: khiêm nhường (nhờ người trên); もらいます: trung tính', NULL, NULL, '{}', NULL, 43, '人に何かをVていただきます／Vてもらいます', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('a0b65def-4be5-41b1-9915-fc8c5d8c199e', 'N4', '人が(は)何かをVてくださいます／くれます', 'Ai đó làm gì cho tôi', 'Chủ ngữ là người làm hành động, くださいます là kính ngữ', 'N1が（は） N2に N3をV(て形) くださいます／くれます', 'Diễn tả việc ai đó chủ động làm gì đó cho mình (có sắc thái biết ơn)', 'くださいます: kính ngữ (người trên làm cho mình); くれます: trung tính', NULL, NULL, '{}', NULL, 43, '人が(は)何かをVてくださいます／くれます', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('5dce2c42-e3fd-4001-8c71-9c1e666a430c', 'N4', 'N1にN2をV', 'Mua/làm N2 để làm quà, kỉ niệm cho N1', 'N1 (dịp/mục đích) + に thường đi cùng động từ mua/chọn', 'N1（お土産／記念など）に N2を 買います／選びます', 'Diễn tả việc mua hoặc chọn một thứ gì đó để làm quà/kỷ niệm cho một dịp', NULL, NULL, NULL, '{}', NULL, 43, 'N1にN2をV', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('d81c5d74-1e44-431a-ac69-76349a62a9b8', 'N4', 'Vる／Nのために、〜', 'Vì ~, để ~, cho ~ (mục đích)', 'ために nêu mục đích cần đạt được cho hành động ở vế sau', 'V(thể từ điển)／N + の + ために、〜', 'Nêu mục đích của hành động ở vế sau', NULL, NULL, NULL, '{}', NULL, 43, 'Vる／Nのために、〜', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('dccdf471-d6f2-430b-9ac3-b383cb0a4e47', 'N4', 'Vるの／Nに、〜', 'Dùng để làm gì / đánh giá hữu ích, cần thiết / tốn thời gian, tiền bạc', 'のに biến mệnh đề động từ thành cụm danh từ đóng vai trò bổ ngữ mục đích', 'V(thể từ điển)／N + のに、〜', NULL, NULL, NULL, NULL, '{}', NULL, 43, 'Vるの／Nに、〜', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('ada779fa-fad6-4bd1-aa67-1435b1b4b079', 'N4', '数量詞＋は〜', 'Tối thiểu, ít nhất là ~', 'は sau số lượng nhấn mạnh mức tối thiểu cần đạt', '[Số lượng] + は + [đủ/cần thiết]', 'Nêu số lượng tối thiểu cần có để thực hiện việc gì', NULL, NULL, NULL, '{}', NULL, 43, '数量詞＋は〜', 'pdf', 'ok')
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('3cfdded9-8c9b-48ca-9eb7-72b7be0e319e', 'dccdf471-d6f2-430b-9ac3-b383cb0a4e47', 1, 'Dùng để làm gì (Vるの／Nに + 使う)', 'V(thể từ điển)／N + のに + 使います', NULL, NULL, 43, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('df58e22a-42e1-4e69-a8be-49a65ef91ed9', 'dccdf471-d6f2-430b-9ac3-b383cb0a4e47', 2, 'Đánh giá hữu ích/cần thiết (Vるの／Nに + 役に立つ／要る／いい／便利／必要だ)', 'V(thể từ điển)／N + のに + 便利です／必要です／いいです', NULL, NULL, 43, 'pdf');
